import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import type {ChatSession} from '../types/session.js';

// @spec specs/hal-engine-config-hooks/spec.md#7
it('reports and cleans up a failed beforeSession before rejecting with the original error', async () => {
  const session: ChatSession = {
    sessionId: 'failed-start',
    userId: 'user',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const failure = new Error('initialization failed after allocating a resource');
  const resources = new Set<ChatSession>();
  const events: string[] = [];
  const errors: {sameSession: boolean; sameError: boolean}[] = [];
  const cleaned: boolean[] = [];
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'You are an assistant.'}),
    undefined,
    {
      hooks: {
        beforeSession: async current => {
          resources.add(current);
          events.push('beforeSession');
          throw failure;
        },
        beforeUserInput: async (_current, message) => {
          events.push('beforeUserInput');
          return message;
        },
        beforeModelResponse: async (_current, prompt) => {
          events.push('beforeModelResponse');
          return prompt;
        },
        onError: async (current, error) => {
          await Promise.resolve();
          errors.push({sameSession: current === session, sameError: error === failure});
          events.push('onError');
        },
        afterSession: async current => {
          await Promise.resolve();
          cleaned.push(current === session && resources.delete(current));
          events.push('afterSession');
        },
      },
    }
  );

  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({sameRejection: rejection === failure, events, errors, cleaned, resourcesRemaining: resources.size}).toEqual({
    sameRejection: true,
    events: ['beforeSession', 'onError', 'afterSession'],
    errors: [{sameSession: true, sameError: true}],
    cleaned: [true],
    resourcesRemaining: 0,
  });
});
''')
